    static func availability(_ row: Row) -> String {
        switch row.rounds.count {
        case 4: return "All four rounds reported · final capture"
        case 0: return "Round scores unavailable · final capture"
        default: return "\(row.rounds.count) rounds reported · final finish unavailable · final capture"
        }
    }

    static func record(_ row: Row) -> GolfWinnerArchiveRoundRecord10868 {
        var rounds = row.rounds.map {
