        if !row.rounds.isEmpty {
            for missing in (1...4) where !row.rounds.contains(where: { $0.round == missing }) {
                rounds.append(GolfRoundScore10868(label: "R\(missing)", value: .unreported(words: "Not reported")))
            }
        }
        let total: FieldChooserReading10868 = row.score.map {
            FieldChooserReading10868(label: "Reported score",
                                     value: .recorded(text: scoreWords($0),
                                                      detail: "Final classification · captured \(evidence.event.actualCapturedAt)"))
        } ?? FieldChooserReading10868(label: "Reported score", value: .missing("Unavailable"))
        return GolfWinnerArchiveRoundRecord10868(ref: ref(row), rounds: rounds, total: total,
                                                 availability: availability(row), summary: summary(row))
    }

    static func runs(_ row: Row) -> [FieldHistoryRun10868] {
        var runs: [FieldHistoryRun10868] = []
        var current: [FieldHistoryPoint10868] = []
        var segment: Int?
        for point in row.history {
            if let open = segment, open != point.segment {
                runs.append(FieldHistoryRun10868(id: "\(row.key)#\(open)", points: current))
                current = []
            }
            segment = point.segment
            current.append(FieldHistoryPoint10868(id: "\(row.key)@\(point.t)", x: Double(point.t), probability: point.value,
                                                  style: point.phase == "before" ? .hollow : .filled))
        }
        if let open = segment, !current.isEmpty {
            runs.append(FieldHistoryRun10868(id: "\(row.key)#\(open)", points: current))
        }
        return runs
    }

