        XCTAssertEqual(rows.filter { $0.rounds.count == 4 }.count, 70)
        XCTAssertEqual(rows.filter { $0.score == nil }.count, 4)
        XCTAssertEqual(rows.filter(\.result).count, 1)

        let winner = Self.winner
        XCTAssertEqual(winner.name, "Adrian Meronk")
        XCTAssertEqual(winner.ticker, "KXDPWORLDTOUR-ALDLC26-AMER")
        XCTAssertEqual(winner.key, "field-62455818.json:236001215")
        XCTAssertEqual(winner.athleteID, "10839")
        XCTAssertEqual(winner.score, "-20")
        XCTAssertEqual(winner.rounds.map(\.strokes), [71, 66, 63, 68])
        XCTAssertEqual(winner.rounds.map(\.relative), [-1, -6, -9, -4])
        XCTAssertEqual(winner.baseline?.value, 0.004)
        XCTAssertEqual(winner.baseline?.volume, 1374.19)
        XCTAssertEqual(winner.baseline?.t, 1790812800)
        XCTAssertEqual(winner.baseline?.at, "2026-10-01T00:00:00+00:00")
        XCTAssertEqual(winner.final.opening_probability, 0.0035)
        XCTAssertEqual(winner.final.probability, 1.0)
        XCTAssertEqual(winner.final.resolution_source, "api_settlement")

        let morrison = Self.named("James Morrison")
        XCTAssertEqual(morrison.rounds.map(\.round), [1, 2, 3])
        XCTAssertEqual(morrison.score, "-1")
        let campillo = Self.named("Jorge Campillo")
        XCTAssertTrue(campillo.rounds.isEmpty)
        XCTAssertNil(campillo.score)
        let mansell = Self.named("Richard Mansell")
        XCTAssertNil(mansell.baseline)
        XCTAssertEqual(mansell.score, "-11")
        XCTAssertEqual(mansell.rounds.count, 4)

        for row in rows {
            XCTAssertEqual(row.final.source, "kalshi", row.key)
            XCTAssertEqual(row.final._market_id, 62455818, row.key)
            XCTAssertEqual(row.final.outcome_name, row.name, row.key)
            XCTAssertTrue(row.rules.hasPrefix("If \(row.name) wins the Alfred Dunhill Links Championship, then the market resolves to Yes.\n"), row.key)
            XCTAssertEqual(row.final.probability, row.result ? 1 : 0, "the settlement is a result, never a chance: \(row.key)")
            if let baseline = row.baseline {
                XCTAssertTrue(row.history.contains { $0.t == baseline.t && $0.value == baseline.value && $0.phase == "before" }, row.key)
                XCTAssertEqual(baseline.interval, 60)
            }
            for (a, b) in zip(row.history, row.history.dropFirst()) {
                XCTAssertGreaterThan(b.t, a.t, row.key)
                XCTAssertEqual(a.segment == b.segment, b.t - a.t <= 7200, "segments break exactly at gaps over two hours: \(row.key)")
            }
            for point in row.history {
                XCTAssertTrue(point.value > 0 && point.value < 1 && point.volume > 0, row.key)
                XCTAssertEqual(point.interval, 60)
            }
            if let score = row.score {
                XCTAssertEqual(score == "E" ? 0 : Int(score), row.rounds.reduce(0) { $0 + $1.relative },
                               "the retained total agrees with its rounds (evidence only, never computed by the page): \(row.key)")
            }
        }
    }

