    func testTheHeroShowsTheWinnerTotalAndOwnDatedPreEventChanceNeverTheOpeningOrSettlement() throws {
        let page = Self.page(Self.input(), log: Log())
        let headline = try XCTUnwrap(page.headlineContent())
        let model = FieldHeadlineModel10868(headline.input)
        XCTAssertEqual(model.title, "Alfred Dunhill Links Championship")
        let competitor = try XCTUnwrap(model.competitors.first)
        XCTAssertEqual(model.competitors.count, 1)
        XCTAssertEqual(competitor.resolution.original?.name, "Adrian Meronk")
        XCTAssertEqual(competitor.metrics, [
            .reading(FieldChooserReading10868(label: "Pre-event win chance",
                                              value: .recorded(text: "0.4%", detail: "Hour-ending trade · 2026-10-01T00:00:00+00:00"))),
            .reading(FieldChooserReading10868(label: "Tournament result",
                                              value: .recorded(text: "Winner · −20",
                                                               detail: "Final classification · captured 2026-10-12T08:22:55.285157+00:00"))),
        ])
        XCTAssertEqual(model.state?.figure, "−20")
        XCTAssertEqual(model.state?.caption, "Tournament winner")
        // The tied raw value is the baseline's, never the opening field or the settlement.
        let pair = try XCTUnwrap(headline.input.pairs.first)
        XCTAssertEqual(pair.before?.probability, 0.004)
        XCTAssertNotEqual(pair.before?.probability, Self.winner.final.opening_probability)
        XCTAssertNotEqual(pair.before?.probability, Self.winner.final.probability)
        XCTAssertFalse(model.keyIsHollow, "the final keys are filled")
        // A changed raw value no longer ties: the figure is not shown.
        var untied = headline.input
        untied = FieldHeadlineInput10868(
            scope: untied.scope, catalogue: untied.catalogue, displayed: untied.displayed,
            pairs: [FieldMovementPair10868(ref: pair.ref, before: FieldMovementObservation10868(
                probability: Self.winner.final.opening_probability,
                reading: FieldChooserReading10868(label: "Pre-event win chance", value: .recorded(text: "0.35%", detail: "Opening field"))),
                                           later: nil, movement: nil, observation: nil)],
            finishes: untied.finishes, state: untied.state, phase: untied.phase, copy: untied.copy,
            unavailableWords: untied.unavailableWords)
        let untiedMetrics = FieldHeadlineModel10868(untied).competitors.first?.metrics ?? []
        XCTAssertFalse(untiedMetrics.flatMap { Self.words($0) }.contains("0.35%"))
        XCTAssertFalse(untiedMetrics.flatMap { Self.words($0) }.contains("0.4%"))
    }

    func testTheHeroMountsOnlyAtItsOwnFinalPhaseWithAPositiveControl() {
        for phase in [FieldOutlookPhase10868.before, .during] {
            let page = Self.page(Self.input(headlinePhase: phase), log: Log())
            XCTAssertNil(page.model.headline, "\(phase)")
            XCTAssertNil(page.headlineContent(), "\(phase)")
            let words = Self.reachable(page)
            XCTAssertTrue(words.contains(Self.headlineUnavailable), "\(phase)")
            XCTAssertFalse(Self.mentions(words, "Tournament winner"), "\(phase)")
            XCTAssertFalse(Self.mentions(words, "Winner · −20"), "\(phase)")
        }
        // Positive control: the same guard sees the final hero.
        let words = Self.reachable(Self.page(Self.input(), log: Log()))
        XCTAssertTrue(Self.mentions(words, "Tournament winner"))
        XCTAssertTrue(Self.mentions(words, "Winner · −20"))
        XCTAssertFalse(words.contains(Self.headlineUnavailable))
        // Meaning-aware tokens: a fragment of a word is not a mention.
        XCTAssertFalse(Self.mentions(["Winners"], "Winner"))
        XCTAssertTrue(Self.mentions(["Tournament winner"], "winner"))
    }

    // MARK: Anchor

    func testTheHistoryCopyKeepsEveryPointRunScaleAndControlAndOnlyChangesHeightAndExpand() {
        for row in [Self.winner, Self.named("Matt Fitzpatrick"), Self.named("Richard Mansell"), Self.named("James Morrison")] {
            for full in [false, true] {
                let input = Self.input(historyRow: row, historySelection: Self.ref(row), full: full)
                let model = Model(input)
                let page = model.history(reader: false)
                let reader = model.history(reader: true)
                XCTAssertEqual(page, input.history, row.name)
                XCTAssertEqual(reader.series, input.history.series)
                XCTAssertEqual(reader.ceiling, input.history.ceiling)
                XCTAssertEqual(reader.scale, input.history.scale)
                XCTAssertEqual(reader.markKey, input.history.markKey)
                XCTAssertEqual(reader.notes, input.history.notes)
                XCTAssertNil(reader.expand)
                XCTAssertEqual(reader.plotHeight, 320)
                let series = input.history.series[0]
                XCTAssertEqual(FieldHistoryGeometry10868.marks(series, in: page).count, row.history.count,
                               "every recorded close is placed on its own scale: \(row.name) full=\(full)")
                XCTAssertEqual(FieldHistoryGeometry10868.lines(series, in: page).count,
                               Self.runs(row).filter { $0.points.count >= 2 }.count, "runs never join across a gap: \(row.name)")
                XCTAssertEqual(series.runs.flatMap(\.points).filter { $0.style == .hollow }.count,
                               row.history.filter { $0.phase == "before" }.count)
                XCTAssertFalse(series.runs.flatMap(\.points).contains { $0.probability == 1 || $0.probability == 0 },
                               "no settlement or zero endpoint: \(row.name)")
                if full {
                    XCTAssertEqual(input.history.ceiling, 1)
                } else {
                    XCTAssertGreaterThanOrEqual(input.history.ceiling, row.history.map(\.value).max() ?? 0)
                }
            }
        }
        // The full-size height is finite and never shorter.
        for (owner, expected) in [(CGFloat?.none, CGFloat(200)), (.some(.nan), 200), (.some(-5), 200),
                                  (.some(150), 200), (.some(.infinity), 200), (.some(480), 480)] {
            let model = Model(Self.input(readerPlotHeight: owner))
            XCTAssertEqual(model.history(reader: true).plotHeight, expected, "\(String(describing: owner))")
            XCTAssertEqual(model.history(reader: false).plotHeight, 200)
        }
        let unusable = Model(Self.input())
        let broken = FieldHistoryGeometry10868.plotHeight(.nan)
        XCTAssertTrue(broken.isFinite && broken > 0)
        XCTAssertGreaterThanOrEqual(FieldHistoryGeometry10868.plotHeight(unusable.history(reader: true).plotHeight),
                                    FieldHistoryGeometry10868.plotHeight(unusable.history(reader: false).plotHeight))
    }

