    func testEveryOriginalHasItsOwnReadoutBaselineMissingnessAndRoundRecord() {
        let model = Model(Self.input())
        var baselines = 0
        var pointTotal = 0
        var roundTotal = 0
        for row in Self.rows {
            guard case .shown(let readout) = model.readout(Self.ref(row)) else {
                XCTFail("\(row.name) must resolve")
                continue
            }
            XCTAssertEqual(readout.original.name, row.name)
            XCTAssertEqual(readout.chance, Self.chance(row))
            if case .recorded = readout.chance.value { baselines += 1 }
            XCTAssertEqual(readout.resultWords, row.result ? "Won" : "Lost")
            XCTAssertEqual(readout.record, Self.record(row))
            XCTAssertEqual(readout.availability, Self.availability(row))
            pointTotal += readout.original.preview.history?.segments.reduce(0) { $0 + $1.count } ?? 0
            roundTotal += readout.record?.rounds.filter {
                if case .reported = $0.value { return true }
                return false
            }.count ?? 0
            switch row.score {
            case nil: XCTAssertEqual(readout.score.value, .missing("Unavailable"), row.name)
            case let score?: XCTAssertEqual(readout.score.value, .recorded(text: Self.scoreWords(score),
                                                                         detail: "Final classification · captured 2026-10-12T08:22:55.285157+00:00"))
            }
        }
        XCTAssertEqual(baselines, 137)
        XCTAssertEqual(pointTotal, 3888)
        XCTAssertEqual(roundTotal, 571)
    }

    func testWinnerNonwinnerPartialAbsentAndNoBaselineGolfersKeepTheirOwnWords() throws {
        let model = Model(Self.input())
        struct Unresolved: Error { let name: String }
        func shown(_ name: String) throws -> GolfWinnerArchiveReadout10868 {
            guard case .shown(let readout) = model.readout(Self.ref(Self.named(name))) else {
                XCTFail("\(name) must resolve")
                throw Unresolved(name: name)
            }
            return readout
        }
        let winner = try shown("Adrian Meronk")
        XCTAssertEqual(Model.words(winner), [
            "Adrian Meronk", "Pre-event win chance", "0.4%", "Hour-ending trade · 2026-10-01T00:00:00+00:00",
            "Market result", "Won", "Reported score", "−20", "Final classification · captured 2026-10-12T08:22:55.285157+00:00",
            "All four rounds reported · final capture",
        ])
        let nonwinner = try shown("Matt Fitzpatrick")
        XCTAssertEqual(nonwinner.resultWords, "Lost")
        XCTAssertEqual(nonwinner.chance.value, .recorded(text: "9.7%", detail: "Hour-ending trade · \(Self.named("Matt Fitzpatrick").baseline!.at)"))

        let morrison = try shown("James Morrison")
        XCTAssertEqual(morrison.record?.rounds.map(\.label), ["R1", "R2", "R3", "R4"])
        XCTAssertEqual(morrison.record?.rounds.last?.value, .unreported(words: "Not reported"))
        XCTAssertEqual(morrison.availability, "3 rounds reported · final finish unavailable · final capture")
        XCTAssertEqual(morrison.chance.value, .recorded(text: "0.1%", detail: "Hour-ending trade · 2026-09-30T03:00:00+00:00"),
                       "the baseline, never the 0.15 opening field")
        XCTAssertEqual(GolfRoundScoreGeometry10868.bar(morrison.record!.rounds[3].value, scale: Self.scale), .unplaced)

        let campillo = try shown("Jorge Campillo")
        XCTAssertEqual(campillo.record?.rounds, [])
        XCTAssertEqual(campillo.score.value, .missing("Unavailable"))
        XCTAssertEqual(campillo.chance.value, .missing("No qualifying pre-event trade captured"))
        XCTAssertFalse(GolfRoundScorePresentation10868.plots(campillo.record?.rounds ?? [], scale: Self.scale))

        let mansell = try shown("Richard Mansell")
        XCTAssertEqual(mansell.chance.value, .missing("No qualifying pre-event trade captured"))
        XCTAssertEqual(mansell.score.value, .recorded(text: "−11", detail: "Final classification · captured 2026-10-12T08:22:55.285157+00:00"))
        XCTAssertEqual(mansell.record?.rounds.count, 4)

        // Partial and absent rounds are never a missed cut or a withdrawal.
        let words = Self.reachable(Self.page(Self.input(featured: [morrison.original.ref, campillo.original.ref, mansell.original.ref]), log: Log()))
        for token in ["missed cut", "Missed cut", "MC", "withdrawn", "Withdrawn", "WD"] {
            XCTAssertFalse(Self.mentions(words, token), token)
        }
        XCTAssertTrue(Self.mentions(words, "Not reported"), "positive control: the partial round's own words are reached")
    }

    // MARK: Round geometry

    func testRoundBarsSitOnTheOwnersSymmetricScaleFromTheZeroReference() {
        let rect = CGRect(x: 0, y: 0, width: 40, height: 100)
        let rounds = Self.record(Self.winner).rounds
        XCTAssertEqual(rounds.map { GolfRoundScoreGeometry10868.bar($0.value, scale: Self.scale) },
                       [.value(fraction: -0.1), .value(fraction: -0.6), .value(fraction: -0.9), .value(fraction: -0.4)])
        let fills = rounds.map { GolfRoundScoreGeometry10868.fill(GolfRoundScoreGeometry10868.bar($0.value, scale: Self.scale), in: rect) }
        XCTAssertEqual(fills.map { $0?.minY }, [50, 50, 50, 50], "under par runs down from the zero line")
        XCTAssertEqual(fills.compactMap { $0?.height }.map { Double($0) }, [5, 30, 45, 20])

        let over = GolfRoundScoreValue10868.reported(relative: 8, text: "+8", detail: nil)
        XCTAssertEqual(GolfRoundScoreGeometry10868.fill(GolfRoundScoreGeometry10868.bar(over, scale: Self.scale), in: rect),
                       CGRect(x: 0, y: 10, width: 40, height: 40), "over par runs up")
        let even = GolfRoundScoreValue10868.reported(relative: 0, text: "E", detail: nil)
        XCTAssertEqual(GolfRoundScoreGeometry10868.bar(even, scale: Self.scale), .value(fraction: 0))
        XCTAssertNil(GolfRoundScoreGeometry10868.fill(.value(fraction: 0), in: rect), "a level round is the zero mark, not a bar")
        XCTAssertEqual(GolfRoundScoreGeometry10868.bar(.reported(relative: 10, text: "+10", detail: nil), scale: Self.scale), .value(fraction: 1))
        XCTAssertEqual(GolfRoundScoreGeometry10868.bar(.reported(relative: 12, text: "+12", detail: nil), scale: Self.scale), .offScale(over: true))
        XCTAssertEqual(GolfRoundScoreGeometry10868.bar(.reported(relative: -11, text: "−11", detail: nil), scale: Self.scale), .offScale(over: false))
        XCTAssertEqual(GolfRoundScoreGeometry10868.bar(.reported(relative: .nan, text: "?", detail: nil), scale: Self.scale), .unplaced)
        XCTAssertEqual(GolfRoundScoreGeometry10868.bar(.unreported(words: "Not reported"), scale: Self.scale), .unplaced)
        let broken = GolfRoundScoreScale10868(limit: 0, ticks: [], words: "")
        XCTAssertEqual(GolfRoundScoreGeometry10868.bar(over, scale: broken), .unplaced)
        XCTAssertFalse(GolfRoundScorePresentation10868.plots(rounds, scale: broken))

        XCTAssertEqual(GolfRoundScoreGeometry10868.y(10, scale: Self.scale, in: rect), 0)
        XCTAssertEqual(GolfRoundScoreGeometry10868.y(0, scale: Self.scale, in: rect), 50)
        XCTAssertEqual(GolfRoundScoreGeometry10868.y(-10, scale: Self.scale, in: rect), 100)
        XCTAssertNil(GolfRoundScoreGeometry10868.y(11, scale: Self.scale, in: rect))
        XCTAssertEqual(GolfRoundScoreGeometry10868.columns(count: 4, in: CGRect(x: 0, y: 0, width: 100, height: 10), spacing: 4).map(\.width),
                       [22, 22, 22, 22])
        XCTAssertTrue(GolfRoundScoreGeometry10868.columns(count: 0, in: rect, spacing: 4).isEmpty)

        // Every one of the 571 reported rounds is placed at its own raw fraction.
        var placed = 0
        for row in Self.rows {
            for (round, shown) in zip(row.rounds, Self.record(row).rounds) {
                XCTAssertEqual(GolfRoundScoreGeometry10868.bar(shown.value, scale: Self.scale),
                               .value(fraction: Double(round.relative) / 10), row.name)
                placed += 1
            }
        }
        XCTAssertEqual(placed, 571)
    }

