        let reversed = Model(Self.input(featured: featured.reversed().map { Self.ref($0) }))
        XCTAssertEqual(reversed.tiles.compactMap { $0.readout?.original.name }, featured.reversed().map(\.name))
        // A repeated, unknown or foreign reference is an unavailable tile; neighbours keep theirs.
        let foreign = Ref(scope: "other", source: "kalshi", marketID: "62455818", outcomeID: String(Self.winner.final.id))
        let unknown = Ref(scope: Self.scope, source: "kalshi", marketID: "62455818", outcomeID: "0")
        let odd = Model(Self.input(featured: [Self.winnerRef, Self.ref(featured[1]), Self.winnerRef, foreign, unknown]))
        XCTAssertEqual(odd.tiles.map { $0.readout?.original.name }, [nil, "Matt Fitzpatrick", nil, nil, nil])
        XCTAssertEqual(odd.tiles.map(\.isSelected), [false, false, false, false, false])
        XCTAssertEqual(odd.spoken(odd.tiles[0]), "Golfer unavailable in this update")
        XCTAssertNil(odd.chooseAction(odd.tiles[0], canChoose: true))
        XCTAssertEqual(odd.chooseAction(odd.tiles[1], canChoose: true), Self.ref(featured[1]))
        XCTAssertNil(odd.chooseAction(odd.tiles[1], canChoose: false))
        // A duplicated round record is no record: the copy's words, not a borrowed total.
        let duplicated = Model(Self.input(roundRows: Self.rows + [Self.winner]))
        guard case .shown(let readout) = duplicated.readout(Self.winnerRef) else { return XCTFail("winner must resolve") }
        XCTAssertNil(readout.record)
        XCTAssertEqual(readout.score.value, .missing("Unavailable"))
        XCTAssertEqual(readout.availability, "Round scores unavailable")
    }

    // MARK: Compact scorecard readout (Design G1)

    func testTheCompactScorecardMountsTheChosenGolfersOwnReadoutAndExactDetails() throws {
        // The compact card mounts the entry, then that golfer's readout.
        let compact = Page.scorecardParts(focused: false)
        let entry = try XCTUnwrap(compact.firstIndex(of: .entry))
        XCTAssertEqual(compact.firstIndex(of: .readout), entry + 1, "the compact readout follows the scorecard entry")
        XCTAssertEqual(Page.scorecardParts(focused: true),
                       [.eyebrow, .title, .entry, .readout, .rounds, .featuredTitle, .caption, .tiles, .legend, .note],
                       "the full reader is unchanged")
        let featuredNames = Set(Self.featured.map(\.name))
        let captured = "Final classification · captured 2026-10-12T08:22:55.285157+00:00"
        let cases: [(String, [String])] = [
            ("Richard Mansell", ["Richard Mansell", "Pre-event win chance", "No qualifying pre-event trade captured",
                                 "Market result", "Lost", "Reported score", "−11", captured,
                                 "All four rounds reported · final capture"]),
            ("James Morrison", ["James Morrison", "Pre-event win chance", "0.1%", "Hour-ending trade · 2026-09-30T03:00:00+00:00",
                                "Market result", "Lost", "Reported score", "−1", captured,
                                "3 rounds reported · final finish unavailable · final capture"]),
            ("Jorge Campillo", ["Jorge Campillo", "Pre-event win chance", "No qualifying pre-event trade captured",
                                "Market result", "Lost", "Reported score", "Unavailable",
                                "Round scores unavailable · final capture"]),
        ]
        for (name, readout) in cases {
            XCTAssertFalse(featuredNames.contains(name), "\(name) is not a featured tile")
            let row = Self.named(name)
            let log = Log()
            let input = Self.input(scorecardSelected: Self.ref(row))
            let page = Self.page(input, log: log)
            XCTAssertTrue(page.model.tiles.allSatisfy { !$0.isSelected }, name)
            let place = Page.Place.stream(Self.activation(log))
            let words = page.scorecardWords(focused: false, at: place)
            let start = try XCTUnwrap(words.firstIndex(of: "Golfer in scorecard"), name)
            XCTAssertEqual(Array(words[start..<min(words.count, start + 3 + readout.count + 1)]),
                           ["Golfer in scorecard", name, "Change"] + readout + ["Details & timing"], name)
            // The same readout the full reader shows; the history golfer is untouched.
            XCTAssertTrue(page.scorecardWords(focused: true, at: .reader).contains(name))
            XCTAssertEqual(page.model.entryName(.history), "Adrian Meronk")
            // Details: the stream's one interaction, then that golfer's exact original.
            try XCTUnwrap(page.detailsAction(.scorecard, at: place))()
            XCTAssertEqual(log.events, ["stream:\(StoryStreamPresentation10868.Intent.interaction(scope: Self.streamScope, card: Self.scorecardCard))",
                                        "details:\(row.final.id)"], name)
        }

        // A withdrawn or foreign selection keeps the owner's words and offers no neighbour.
        let mansell = Self.named("Richard Mansell")
        let foreign = Ref(scope: "other", source: "kalshi", marketID: "62455818", outcomeID: String(mansell.final.id))
        for input in [Self.input(Self.rows.filter { $0.key != mansell.key }, scorecardSelected: Self.ref(mansell)),
                      Self.input(scorecardSelected: foreign)] {
            let page = Self.page(input, log: Log())
            let words = page.scorecardWords(focused: false, at: .page)
            let start = try XCTUnwrap(words.firstIndex(of: "Golfer in scorecard"))
            XCTAssertEqual(Array(words[start..<min(words.count, start + 4)]),
                           ["Golfer in scorecard", "Golfer unavailable in this update", "Change", "Golfer unavailable in this update"])
            XCTAssertNil(page.detailsAction(.scorecard, at: .page))
            XCTAssertFalse(words.contains("Details & timing"))
            XCTAssertFalse(words.contains("−11"), "never the withdrawn golfer's score from elsewhere")
        }

        // Mounted body: the compact card is taller with a resolved readout than with
        // the one-line unavailable words — removing the compact readout from the body
        // makes these equal.
        func height(_ selected: Ref) -> CGFloat {
            let host = hostForMeasurement(Self.page(Self.input(scorecardSelected: selected), log: Log())
                .environment(\.horizontalSizeClass, .compact), at: .large)
            host.view.frame = CGRect(x: 0, y: 0, width: 375, height: 2000)
            host.view.setNeedsLayout()
            host.view.layoutIfNeeded()
            return host.sizeThatFits(in: CGSize(width: 375, height: .greatestFiniteMagnitude)).height
        }
        XCTAssertGreaterThan(height(Self.ref(mansell)), height(foreign) + 40)
    }

    // MARK: Selections

    func testHistoryAndScorecardSelectionsAreIndependentAndSurviveOwnerFrames() throws {
        let fitz = Self.named("Matt Fitzpatrick")
        let base = Self.input(historySelection: Self.winnerRef, scorecardSelected: Self.ref(fitz))
        let model = Model(base)
        guard case .shown(let history) = model.readout(role: .history),
              case .shown(let scorecard) = model.readout(role: .scorecard) else { return XCTFail("both resolve") }
        XCTAssertEqual(history.original.name, "Adrian Meronk")
        XCTAssertEqual(scorecard.original.name, "Matt Fitzpatrick")
        XCTAssertEqual(model.tiles.filter(\.isSelected).map { $0.readout?.original.name }, ["Matt Fitzpatrick"])
        XCTAssertEqual(model.entryName(.history), "Adrian Meronk")
        XCTAssertEqual(model.entryName(.scorecard), "Matt Fitzpatrick")

        // A tile acts for the scorecard role only; the history chooser for the history role only.
        let log = Log()
        let page = Self.page(base, log: log)
        try XCTUnwrap(page.tileAction(model.tiles[0], at: .reader))()
        try XCTUnwrap(Self.page(base, .chooser(.history), log: log).chooserContent(.history)?.onChoose)(Self.ref(Self.rows[5]))
        XCTAssertEqual(log.events, ["choose:scorecard:\(Self.winner.final.id)", "hold", "choose:history:\(Self.rows[5].final.id)"])

        // Owner frames: reordered keeps both; omission shows the owner's words
        // for that role only, never a neighbour; restoration returns the exact golfer.
        let reordered = Model(Self.input(Self.rows.reversed(), historySelection: Self.winnerRef, scorecardSelected: Self.ref(fitz)))
        XCTAssertEqual(reordered.readout(role: .history), model.readout(role: .history))
        XCTAssertEqual(reordered.readout(role: .scorecard), model.readout(role: .scorecard))
        let withoutWinner = Self.rows.filter { !$0.result }
        let omitted = Model(Self.input(withoutWinner, historySelection: Self.winnerRef, scorecardSelected: Self.ref(fitz)))
        XCTAssertEqual(omitted.readout(role: .history), .unavailable("Golfer unavailable in this update"))
        XCTAssertEqual(omitted.readout(role: .scorecard), model.readout(role: .scorecard))
        XCTAssertNil(omitted.tiles[0].readout, "the withdrawn winner's tile borrows nothing")
        let restored = Model(Self.input(historySelection: Self.winnerRef, scorecardSelected: Self.ref(fitz)))
        XCTAssertEqual(restored.readout(role: .history), model.readout(role: .history))

        // Duplicate, foreign and unknown identities never resolve to a neighbour.
        let duplicate = Model(Self.input(Self.rows + [Self.winner], historySelection: Self.winnerRef, scorecardSelected: Self.ref(fitz)))
        XCTAssertEqual(duplicate.readout(role: .history), .unavailable("Golfer unavailable in this update"))
        let foreign = Ref(scope: "other", source: "kalshi", marketID: "62455818", outcomeID: String(Self.winner.final.id))
        let unknown = Ref(scope: Self.scope, source: "kalshi", marketID: "62455818", outcomeID: "0")
        for ref in [foreign, unknown] {
            let odd = Model(Self.input(historySelection: ref, scorecardSelected: ref))
            XCTAssertEqual(odd.readout(role: .history), .unavailable("Golfer unavailable in this update"))
            XCTAssertEqual(odd.readout(role: .scorecard), .unavailable("Golfer unavailable in this update"))
            XCTAssertEqual(odd.entryName(.history), "Golfer unavailable in this update")
            XCTAssertTrue(odd.tiles.allSatisfy { !$0.isSelected })
        }
        // No held golfer: nothing drawn, no entry name, no Details.
        let none = Self.page(Self.input(historySelection: nil, scorecardSelected: nil), log: Log())
        XCTAssertEqual(none.model.readout(role: .history), .notHeld)
        XCTAssertNil(none.model.entryName(.scorecard))
        XCTAssertNil(none.detailsAction(.history, at: .page))
        // The chooser's own notice for its withdrawn selection.
        let notice = FieldChooserModel10868(try XCTUnwrap(omitted.chooserPresentation(.history))).selectionNotice
        XCTAssertEqual(notice, "Golfer unavailable")
    }

    // MARK: Chooser

    func testTheChooserReachesAll171ThroughSixBandsOfBoundedPagesNeverAWallOfButtons() throws {
        let expected: [(String, Int, String, String)] = [
            ("A–C", 34, "Adri Arnaus", "Connor Syme"), ("D–G", 29, "Daniel Brown", "Guido Migliozzi"),
            ("H–L", 41, "Haydn Porteous", "Luke List"), ("M–P", 29, "Marc Leishman", "Peter Uihlein"),
            ("Q–S", 24, "Quentin Debove", "Shubhankar Sharma"), ("T–Z", 14, "Thomas Detry", "Zander Lombard"),
        ]
        XCTAssertEqual(expected.map(\.0), Self.bands)
        var reached: Set<Ref> = []
        for (band, count, first, last) in expected {
            let members = Self.members(band)
            XCTAssertEqual(members.count, count, band)
            XCTAssertEqual(members.first?.name, first, band)
            XCTAssertEqual(members.last?.name, last, band)
            let pages = Self.pages(band)
            XCTAssertEqual(pages.count, (count + 5) / 6, band)
            for index in pages.indices {
                let log = Log()
                let input = Self.input(historyGroup: Self.groupID(band, index))
                let page = Self.page(input, .chooser(.history), log: log)
                let shown = try XCTUnwrap(page.model.chooserPresentation(.history))
                XCTAssertEqual(shown.browse?.groups.map(\.id), [Self.groupID(band, index)], "one group, not every page")
                let rows = FieldChooserModel10868(shown).groupRows
                XCTAssertLessThanOrEqual(rows.count, 6)
                XCTAssertEqual(rows.compactMap { $0.resolution.original?.name }, pages[index].map(\.name))
                reached.formUnion(rows.compactMap { $0.resolution.original?.ref })
                // Every row chooses its exact golfer for the history role, after one hold.
                let chooser = try XCTUnwrap(page.chooserContent(.history))
                for row in rows { chooser.onChoose?(row.ref) }
                XCTAssertEqual(log.events, rows.flatMap { ["hold", "choose:history:\($0.ref.outcomeID)"] })
            }
            // First, middle and last pages hand back the exact adjacent groups.
            for index in Set([0, pages.count / 2, pages.count - 1]) {
                let navigation = try XCTUnwrap(Model(Self.input(historyGroup: Self.groupID(band, index))).chooserNavigation(.history))
                XCTAssertEqual(navigation.control(navigation.navigation.previous, canControl: true),
                               index > 0 ? .chooseGroup(id: Self.groupID(band, index - 1)) : nil, "\(band) \(index)")
                XCTAssertEqual(navigation.control(navigation.navigation.next, canControl: true),
                               index + 1 < pages.count ? .chooseGroup(id: Self.groupID(band, index + 1)) : nil, "\(band) \(index)")
                XCTAssertEqual(navigation.navigation.bands.map { navigation.control($0, canControl: true) },
                               Self.bands.map { Optional(FieldChooserControl10868.chooseGroup(id: Self.groupID($0, 0))) })
                XCTAssertNil(navigation.control(Target(label: "Next", groupID: "\(band)|99"), canControl: true), "a foreign page id hands back nothing")
                XCTAssertNil(navigation.control(navigation.navigation.next, canControl: false))
            }
        }
        XCTAssertEqual(reached, Set(Self.rows.map { Self.ref($0) }), "every original is reachable, baseline or not")
        XCTAssertEqual(reached.count, 171)

        // The page's navigation control: one hold, then the exact role-tagged group.
        let log = Log()
        let page = Self.page(Self.input(historyGroup: Self.groupID("H–L", 3)), .chooser(.history), log: log)
        let pages = try XCTUnwrap(page.chooserNavigationContent(.history, .pages))
        pages.choose(pages.model.navigation.next)
        pages.choose(pages.model.navigation.previous)
        XCTAssertEqual(log.events, ["hold", "control:history:\(FieldChooserControl10868.chooseGroup(id: "H–L|4"))",
                                    "hold", "control:history:\(FieldChooserControl10868.chooseGroup(id: "H–L|2"))"])

        // Suggested mode: the owner's suggestions, its own group.
        XCTAssertEqual(Self.suggestions.map(\.name), ["Adrian Meronk", "Matt Fitzpatrick", "Tommy Fleetwood"])
        let suggested = try XCTUnwrap(Model(Self.input(scorecardGroup: "suggested")).chooserPresentation(.scorecard))
        XCTAssertEqual(FieldChooserModel10868(suggested).groupRows.compactMap { $0.resolution.original?.name },
                       ["Adrian Meronk", "Matt Fitzpatrick", "Tommy Fleetwood"])
    }

