        let details = try XCTUnwrap(page.originalDetailsContent())
        XCTAssertEqual(details.selection?.identity.market, "KXDPWORLDTOUR-ALDLC26-AMER")
        details.onHistory?(Details.HistoryIntent(selection: details.selection!, entry: .explore, actionID: "explore"))
        let catalogue = try XCTUnwrap(Self.page(Self.input(), .catalogue, log: log, originals: Self.originals(selection: nil)).catalogueContent())
        catalogue.onSelect?(Details.Selection(scope: originals.catalogue!.scope,
                                              identity: Details.Identity(source: "kalshi", market: "KXDPWORLDTOUR-ALDLC26-AMER", side: "yes")))
        XCTAssertEqual(log.events, ["hold", "originalHistory:explore", "hold", "select:KXDPWORLDTOUR-ALDLC26-AMER"])
